Employee employee = new SalariedEmployee("An", 320);
Console.WriteLine($"label:{employee.Label()}/{employee.Points}");
abstract class Employee
{
    protected string Name { get; }
    protected Employee(string name)
    {
        if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException(nameof(name));
        Name = name; Console.WriteLine($"base:{name}");
    }
    public string Label() => Name;
    public abstract int Points { get; }
}
sealed class SalariedEmployee : Employee
{
    public override int Points { get; }
    public SalariedEmployee(string name, int points) : base(name)
    {
        if (points <= 0) throw new ArgumentOutOfRangeException(nameof(points));
        Points = points; Console.WriteLine("derived:ready");
    }
}

