Console.WriteLine($"rectangle:{Configure(new Rectangle())}");
Console.WriteLine($"square:{Configure(new Square())}");
IShape[] shapes = { new FixedRectangle(5, 4), new FixedSquare(4) };
foreach (var shape in shapes) Console.WriteLine($"read-only area:{shape.Area}");
static int Configure(Rectangle rectangle)
{
    rectangle.Width = 5;
    rectangle.Height = 4; // Contract của ví dụ: không thay Width.
    return rectangle.Area; // Caller dựa vào 5 * 4.
}
class Rectangle
{
    public virtual int Width { get; set; }
    public virtual int Height { get; set; }
    public int Area => Width * Height;
}
sealed class Square : Rectangle
{
    private int side;
    public override int Width { get => side; set => side = value; }
    public override int Height { get => side; set => side = value; }
}
interface IShape { int Area { get; } }
sealed record FixedRectangle(int Width, int Height) : IShape { public int Area => Width * Height; }
sealed record FixedSquare(int Side) : IShape { public int Area => Side * Side; }

